CREATE TABLE `admin` (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `category` (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE,
  image VARCHAR(500) NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `fooditem` (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, categoryId INT UNSIGNED NOT NULL,
  name VARCHAR(180) NOT NULL UNIQUE, description TEXT NULL, price DECIMAL(10,2) NOT NULL,
  image VARCHAR(500) NULL, isVeg TINYINT(1) NOT NULL DEFAULT 1,
  isAvailable TINYINT(1) NOT NULL DEFAULT 1, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_food_category FOREIGN KEY (categoryId) REFERENCES category(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `customer` (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, mobileNumber VARCHAR(20) NOT NULL UNIQUE,
  name VARCHAR(160) NULL, birthday DATE NULL, anniversary DATE NULL,
  referralCode VARCHAR(32) NULL UNIQUE, cashbackBalance DECIMAL(10,2) NOT NULL DEFAULT 0,
  createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `customeraddress` (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customerId INT UNSIGNED NOT NULL,
  label VARCHAR(40) NOT NULL, address TEXT NOT NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY customer_address_label (customerId,label), CONSTRAINT fk_address_customer FOREIGN KEY(customerId) REFERENCES customer(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `order` (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, orderNumber VARCHAR(40) NOT NULL UNIQUE,
  customerId INT UNSIGNED NULL, customerName VARCHAR(160) NOT NULL, mobileNumber VARCHAR(20) NOT NULL,
  whatsappNumber VARCHAR(20) NULL, email VARCHAR(190) NULL, address TEXT NULL, tableNumber VARCHAR(40) NULL,
  orderType ENUM('DINE_IN','TAKEAWAY','DELIVERY') NOT NULL DEFAULT 'DINE_IN',
  paymentMethod ENUM('CASH','UPI','CARD') NOT NULL DEFAULT 'UPI',
  totalAmount DECIMAL(10,2) NOT NULL, gstAmount DECIMAL(10,2) NOT NULL DEFAULT 0,
  discountAmount DECIMAL(10,2) NOT NULL DEFAULT 0, cashbackRedeemed DECIMAL(10,2) NOT NULL DEFAULT 0,
  cashbackEarned DECIMAL(10,2) NOT NULL DEFAULT 0, grandTotal DECIMAL(10,2) NOT NULL,
  referralCode VARCHAR(32) NULL, referrerId INT UNSIGNED NULL, referralDiscount DECIMAL(10,2) NOT NULL DEFAULT 0,
  status ENUM('PENDING','PREPARING','COMPLETED','DELIVERED','CANCELLED') NOT NULL DEFAULT 'PENDING',
  confirmedAt DATETIME NULL, preparationStartedAt DATETIME NULL, preparationMinutes INT NULL,
  readyAt DATETIME NULL, deliveredAt DATETIME NULL, customerSessionToken VARCHAR(80) NOT NULL,
  customerSessionExpiresAt DATETIME NOT NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_order_customer FOREIGN KEY(customerId) REFERENCES customer(id) ON DELETE SET NULL,
  CONSTRAINT fk_order_referrer FOREIGN KEY(referrerId) REFERENCES customer(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `cashbacktransaction` (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customerId INT UNSIGNED NOT NULL, orderId INT UNSIGNED NULL,
  type ENUM('EARNED','REDEEMED','ADJUSTED') NOT NULL, amount DECIMAL(10,2) NOT NULL,
  balanceAfter DECIMAL(10,2) NOT NULL, note VARCHAR(255) NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX customer_transactions (customerId, createdAt),
  CONSTRAINT fk_cashback_customer FOREIGN KEY(customerId) REFERENCES customer(id) ON DELETE CASCADE,
  CONSTRAINT fk_cashback_order FOREIGN KEY(orderId) REFERENCES `order`(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `orderitem` (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, orderId INT UNSIGNED NOT NULL, foodItemId INT UNSIGNED NOT NULL,
  quantity INT NOT NULL, unitPrice DECIMAL(10,2) NOT NULL, subtotal DECIMAL(10,2) NOT NULL,
  CONSTRAINT fk_item_order FOREIGN KEY(orderId) REFERENCES `order`(id) ON DELETE CASCADE,
  CONSTRAINT fk_item_food FOREIGN KEY(foodItemId) REFERENCES fooditem(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

